class TextNode {
	constructor(data) {
		this.nodeType = 3;
		this.childNodes = [];
		this.parentNode = null;
		this.data = String(data);
	}
	get textContent() {
		return this.data;
	}
	get nextSibling() {
		const i = this.parentNode ? this.parentNode.childNodes.indexOf(this) : -1;
		return i > -1 ? this.parentNode.childNodes[i + 1] || null : null;
	}
}

class Element {
	constructor(tag) {
		this.nodeType = 1;
		this.nodeName = this.localName = tag.toLowerCase();
		this.childNodes = [];
		this.parentNode = null;
		this.attributes = [];
		this.style = { setProperty(k, v) { this[k] = v; }, removeProperty(k) { delete this[k]; } };
		this._innerHTML = '';
	}
	get innerHTML() {
		return this.childNodes.map(serialize).join('');
	}
	set innerHTML(v) {
		this.childNodes = [];
	}
	get textContent() {
		return this.childNodes.map(c => (c.nodeType === 3 ? c.data : c.textContent)).join('');
	}
	set textContent(v) {
		this.childNodes = [];
	}
	appendChild(child) {
		if (child.parentNode) {
			const i = child.parentNode.childNodes.indexOf(child);
			if (i > -1) child.parentNode.childNodes.splice(i, 1);
		}
		this.childNodes.push(child);
		child.parentNode = this;
		return child;
	}
	insertBefore(child, ref) {
		if (child.parentNode) {
			const i = child.parentNode.childNodes.indexOf(child);
			if (i > -1) child.parentNode.childNodes.splice(i, 1);
		}
		const idx = ref ? this.childNodes.indexOf(ref) : -1;
		if (idx > -1) this.childNodes.splice(idx, 0, child);
		else this.childNodes.push(child);
		child.parentNode = this;
		return child;
	}
	removeChild(child) {
		const i = this.childNodes.indexOf(child);
		if (i > -1) this.childNodes.splice(i, 1);
		child.parentNode = null;
		return child;
	}
	get nextSibling() {
		const i = this.parentNode ? this.parentNode.childNodes.indexOf(this) : -1;
		return i > -1 ? this.parentNode.childNodes[i + 1] || null : null;
	}
	addEventListener() {}
	removeEventListener() {}
	setAttribute(k, v) {
		this.attributes.push({ name: k, value: String(v) });
	}
	getAttribute(k) {
		const a = this.attributes.find(a => a.name === k);
		return a ? a.value : null;
	}
	removeAttribute(k) {
		this.attributes = this.attributes.filter(a => a.name !== k);
	}
}

function serialize(n) {
	if (n.nodeType === 3) return n.data;
	let s = '<' + n.nodeName;
	for (const a of n.attributes) s += ` ${a.name}="${a.value}"`;
	s += '>';
	for (const c of n.childNodes) s += serialize(c);
	s += `</${n.nodeName}>`;
	return s;
}

const document = {
	createElement(tag) {
		return new Element(tag);
	},
	createElementNS(ns, tag) {
		return new Element(tag);
	},
	createTextNode(data) {
		return new TextNode(data);
	}
};

global.document = document;

const { render } = require('/testbed/src/index.js');

const root = new Element('div');

// string child
render('a', root);
console.log('string:', root.innerHTML);
if (root.innerHTML !== 'a') throw new Error('string render broken');

// number child
render(42, root);
console.log('number:', root.innerHTML);
if (root.innerHTML !== '42') throw new Error('number render broken');

// bigint child (the issue reproduction)
// eslint-disable-next-line
render(BigInt(5), root);
console.log('bigint:', root.innerHTML);
if (root.innerHTML !== '5') throw new Error('bigint render broken');

// bigint inside element
// eslint-disable-next-line
render({ type: 'span', props: { children: BigInt(123) }, key: null, ref: null, constructor: undefined }, root);
console.log('span>bigint:', root.innerHTML);
if (root.innerHTML !== '<span>123</span>') throw new Error('bigint element render broken');

// re-render to test diffing path with bigint -> bigint
// eslint-disable-next-line
render({ type: 'span', props: { children: BigInt(456) }, key: null, ref: null, constructor: undefined }, root);
console.log('span>bigint rerender:', root.innerHTML);
if (root.innerHTML !== '<span>456</span>') throw new Error('bigint rerender broken');

// bigint -> number swap
render({ type: 'span', props: { children: 42 }, key: null, ref: null, constructor: undefined }, root);
console.log('span>number rerender:', root.innerHTML);
if (root.innerHTML !== '<span>42</span>') throw new Error('number rerender broken');

console.log('ALL OK');

